export function sizesFor(p: Product): string[] {
  if (p.cat === "shoes" || p.cat === "sneakers") return ["36", "37", "38", "39", "40"];
  if (p.cat === "bag" || p.cat === "scarf") return ["One size"];
  if (p.cat === "jeans") return ["25", "26", "27", "28", "29"];
  return ["XS", "S", "M", "L", "XL"];
}

export function hashN(s: string) {
  let h = 7;
  for (const c of s) h = (h * 31 + c.charCodeAt(0)) % 9973;
  return h;
}

/** Same item in other stores. Demo data: derived prices. Real data: matched by the feed importer. */
export function offers(p: Product) {
  const others = (Object.keys(STORES) as StoreName[])
    .filter((s) => s !== p.store)
    .sort((a, b) => hashN(a + p.id) - hashN(b + p.id))
    .slice(0, 2);
  return [
    { store: p.store, price: p.price, best: true },
    { store: others[0], price: p.price + 350, best: false },
    { store: others[1], price: p.price + 600, best: false },
  ];
}

